<?php
namespace App\Http\Controllers; use App\Models\{Deposit,DepositDetail,DepositStatusHistory,Waste,User,AccountLedger,AppNotification}; use App\Http\Requests\StoreDepositRequest; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class DepositController extends Controller {public function index(Request $r){$u=auth()->user();$q=Deposit::with(['customer','officer'])->when($u->role==='nasabah',fn($x)=>$x->where('customer_id',$u->id))->when($r->search,fn($x,$s)=>$x->where(fn($z)=>$z->where('code','like',"%$s%")->orWhereHas('customer',fn($c)=>$c->where('name','like',"%$s%"))))->when($r->status,fn($x,$s)=>$x->where('status',$s));$deposits=$q->latest()->paginate(10)->withQueryString();return view('deposits.index',compact('deposits'));} public function create(){return view('deposits.create',['customers'=>User::where('role','nasabah')->where('is_active',true)->orderBy('name')->get(),'wastes'=>Waste::where('is_active',true)->orderBy('name')->get()]);} public function store(StoreDepositRequest $r){$v=$r->validated();$deposit=DB::transaction(function()use($v){$d=Deposit::create(['code'=>'STR-'.now()->format('YmdHis').'-'.random_int(10,99),'customer_id'=>$v['customer_id'],'officer_id'=>auth()->id(),'deposit_date'=>$v['deposit_date'],'status'=>'pending','notes'=>$v['notes']??null]);$tw=0;$ta=0;foreach($v['items'] as $i){$w=Waste::where('is_active',true)->findOrFail($i['waste_id']);$weight=(float)$i['weight_kg'];$sub=$weight*(float)$w->price_per_kg;DepositDetail::create(['deposit_id'=>$d->id,'waste_id'=>$w->id,'weight_kg'=>$weight,'price_per_kg'=>$w->price_per_kg,'subtotal'=>$sub]);$tw+=$weight;$ta+=$sub;}$d->update(['total_weight'=>$tw,'total_amount'=>$ta]);DepositStatusHistory::create(['deposit_id'=>$d->id,'from_status'=>null,'to_status'=>'pending','changed_by'=>auth()->id(),'notes'=>'Setoran dibuat']);AppNotification::create(['user_id'=>$d->customer_id,'title'=>'Setoran baru','message'=>"Setoran {$d->code} tercatat sebesar Rp ".number_format($ta,0,',','.'),'link'=>route('deposits.show',$d)]);return $d;});return redirect()->route('deposits.show',$deposit)->with('success','Setoran berhasil dibuat dan total dihitung otomatis.');} public function show(Deposit $deposit){$this->authorizeOwner($deposit);$deposit->load(['customer','officer','details.waste','histories.changer']);return view('deposits.show',compact('deposit'));} public function updateStatus(Request $r,Deposit $deposit){abort_unless(in_array(auth()->user()->role,['admin','petugas'],true),403);$data=$r->validate(['status'=>['required','in:weighed,completed,cancelled'],'notes'=>['nullable','string','max:500']]);$allowed=['pending'=>['weighed','cancelled'],'weighed'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[]];abort_unless(in_array($data['status'],$allowed[$deposit->status]??[],true),422,'Perubahan status tidak sesuai urutan.');DB::transaction(function()use($deposit,$data){$old=$deposit->status;$deposit->update(['status'=>$data['status'],'officer_id'=>auth()->id()]);DepositStatusHistory::create(['deposit_id'=>$deposit->id,'from_status'=>$old,'to_status'=>$data['status'],'changed_by'=>auth()->id(),'notes'=>$data['notes']??null]);if($data['status']==='completed'){foreach($deposit->details as $detail){$detail->waste()->increment('stock_kg',$detail->weight_kg);}AccountLedger::firstOrCreate(['reference_type'=>'deposit','reference_id'=>$deposit->id],['customer_id'=>$deposit->customer_id,'type'=>'credit','amount'=>$deposit->total_amount,'description'=>'Saldo dari '.$deposit->code]);}AppNotification::create(['user_id'=>$deposit->customer_id,'title'=>'Status setoran berubah','message'=>"{$deposit->code}: {$old} → {$data['status']}",'link'=>route('deposits.show',$deposit)]);});return back()->with('success','Status setoran berhasil diperbarui.');} private function authorizeOwner(Deposit $d):void{$u=auth()->user();if($u->role==='nasabah'&&$d->customer_id!==$u->id)abort(403,'Bukan data Anda.');}}
